import"./chunk-7CGTOI24.js";var e={slug:"adaptacoes-de-games-no-cinema-2026",title:"2026, o ano em que Hollywood resolveu adaptar todos os games",dek:"Silent Hill, Mario, Mortal Kombat, Resident Evil e Street Fighter em um s\xF3 ano, com Zelda e Minecraft j\xE1 na fila. Por que a onda chegou e o que ela revela.",section:"filmes",kind:"opiniao",tags:["Adapta\xE7\xE3o","Street Fighter","Resident Evil","Nintendo"],date:"2026-10-18",hero:{ref:"movie:1153576",pick:0,alt:"Lutadores em cena do filme Street Fighter"},body:[{p:"Com a estreia de *Street Fighter* nos cinemas brasileiros na \xFAltima quinta-feira (15), 2026 fecha uma sequ\xEAncia dif\xEDcil de ignorar. Em dez meses, cinco grandes adapta\xE7\xF5es de games chegaram \xE0s salas do pa\xEDs. Durante d\xE9cadas, filme baseado em videogame era sin\xF4nimo de trope\xE7o. Agora virou estrat\xE9gia de est\xFAdio."},{h2:"O calend\xE1rio de 2026"},{entry:"movie:680493",title:"Terror em Silent Hill: Regresso Para o Inferno",text:["Christophe Gans, diretor do *Terror em Silent Hill* de 2006, voltou \xE0 cidade em janeiro, agora adaptando a hist\xF3ria de *Silent Hill 2*, com Jeremy Irvine como James Sunderland."]},{entry:"movie:1226863",title:"Super Mario Galaxy: O Filme",text:["A Illumination levou o encanador para o espa\xE7o em abril, com Chris Pratt, Anya Taylor-Joy e Jack Black de volta e Benny Safdie como a voz do Bowser Jr. no original."]},{entry:"movie:931285",title:"Mortal Kombat 2",text:["Em maio, Simon McQuoid retomou o torneio com Karl Urban como Johnny Cage, um dos personagens mais pedidos pelos f\xE3s depois do filme de 2021."]},{entry:"movie:1423191",title:"Resident Evil",text:["Zach Cregger, de *Noites Brutais*, escreveu e dirigiu uma nova vers\xE3o que chegou em setembro. A sinopse acompanha um entregador de \xF3rg\xE3os a caminho do hospital de Raccoon City."]},{entry:"movie:1153576",title:"Street Fighter",text:["Kitao Sakurai dirige Andrew Koji como Ryu, Noah Centineo como Ken e Callina Liang como Chun-Li, com David Dastmalchian como M. Bison e Joe Anoa'i como Akuma. A Capcom aparece entre as produtoras."]},{h2:"Por que agora"},{p:"Nossa leitura \xE9 que tr\xEAs coisas mudaram ao mesmo tempo. A primeira \xE9 geracional: quem cresceu jogando hoje decide o que se produz e o que se assiste. A segunda \xE9 que as donas das marcas passaram a participar da produ\xE7\xE3o, como a Capcom em *Street Fighter* e a Konami em *Silent Hill*, o que reduz a dist\xE2ncia entre o jogo e o filme. A terceira \xE9 a televis\xE3o: depois de s\xE9ries como *The Last of Us* e *Arcane*, ficou dif\xEDcil sustentar que games n\xE3o rendem boas hist\xF3rias."},{quote:"O problema nunca foi adaptar videogame. Era adaptar sem entender por que as pessoas amam aquele jogo."},{h2:"O que vem em 2027"},{p:"A fila continua. *A Lenda de Zelda*, em live-action, tem estreia prevista no Brasil para 6 de maio de 2027, com dire\xE7\xE3o de Wes Ball. Em julho chega *Um Filme Minecraft: Ao Quadrado*, de novo com Jared Hess na dire\xE7\xE3o e com Jack Black e Jason Momoa no elenco."},{ficha:"movie:1177369"},{h2:"O risco da satura\xE7\xE3o"},{p:"Cinco filmes em um ano \xE9 muita coisa. Quando tudo vira adapta\xE7\xE3o, o selo perde o efeito de novidade e cada filme precisa se sustentar sozinho. \xC9 uma boa not\xEDcia: a r\xE9gua sobe. A m\xE1 \xE9 que, se dois ou tr\xEAs fracassarem em sequ\xEAncia, a ind\xFAstria costuma reagir cortando projetos inteiros, n\xE3o s\xF3 os ruins."},{p:"Para quem quer ir al\xE9m do cinema, montamos um [ranking das melhores s\xE9ries baseadas em games](/artigo/series-baseadas-em-games-ranking)."},{box:"Este \xE9 um texto de opini\xE3o. Datas, elencos e equipes v\xEAm do TMDB; n\xE3o citamos n\xFAmeros de bilheteria.",title:"Opini\xE3o"}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{},movies:{680493:{id:680493,title:"Terror em Silent Hill: Regresso Para o Inferno",original:"Return to Silent Hill",overview:"Quando uma carta misteriosa chama James de volta a Silent Hill em busca de seu verdadeiro amor, ele encontra uma cidade antes reconhec\xEDvel, transformada por um mal desconhecido. \xC0 medida que James se aprofunda na escurid\xE3o, ele encontra figuras aterrorizantes, tanto familiares quanto novas, e come\xE7a a questionar sua pr\xF3pria sanidade enquanto luta para entender a realidade e se manter firme por tempo suficiente para salvar seu amor perdido.",poster:"/mRbdOe5vMnY3HXxLnWgRFJHbCPs.jpg",backdrops:["/v0NEB75SZjxY8GS3ho8WeEvjIT3.jpg","/nTbO6UF944b0VZrgypMK5rFYRSW.jpg","/8pUye1LPtIL1Z0hKhgtiax0akI8.jpg","/thX9LNAEEtCpjypCMUB5efItT7g.jpg","/iYtdDPURUXebWX0sbSx3uLNfvPO.jpg"],runtime:106,genres:["Terror","Mist\xE9rio"],cert:"16",release:"2026-01-22",world:"2026-01-21",directors:["Christophe Gans"],writers:["Sandra Vo-Anh","Christophe Gans"],cast:[{name:"Jeremy Irvine",role:"James Sunderland"},{name:"Hannah Emily Anderson",role:"Mary Crane / Angela / Maria / Moth Mary"},{name:"Ljiljana Velimirov",role:"Armless"},{name:"Giulia Pelagatti",role:"Armless / Spider Lady"},{name:"Evie Templeton",role:"Laura"},{name:"Robert Strange",role:"Pyramid Head"}],studios:["Konami","Davis Films"],country:"GB"},931285:{id:931285,title:"Mortal Kombat 2",original:"Mortal Kombat II",overview:"Os campe\xF5es favoritos dos f\xE3s \u2013 agora acompanhados pelo pr\xF3prio Johnny Cage \u2013 s\xE3o colocados uns contra os outros numa sangrenta e derradeira batalha, sem regras ou limites, para derrotar o governo sombrio de Shao Kahn.",poster:"/iILiJSRViTEcF23MHhGCbVm3mfW.jpg",backdrops:["/4EAAwpylq313qrDqpCxulUrXBNF.jpg","/tYvikGoGcmGvo5gkiNwNjzXcxCb.jpg","/sK2l7vWYsbQAAYaB2Gh0PD1QknL.jpg","/ybmfvoIPxQ9Ivy2tEhi6JxufMJL.jpg","/kKffDryQNDBNvj1tllxKDrAUZ3w.jpg"],runtime:116,genres:["A\xE7\xE3o","Fantasia","Aventura"],cert:"18",release:"2026-05-07",world:"2026-05-06",directors:["Simon McQuoid"],writers:["Jeremy Slater"],cast:[{name:"Karl Urban",role:"Johnny Cage"},{name:"Adeline Rudolph",role:"Kitana"},{name:"Ludi Lin",role:"Liu Kang"},{name:"Jessica McNamee",role:"Sonya Blade"},{name:"Martyn Ford",role:"Shao Kahn"},{name:"Josh Lawson",role:"Kano"}],studios:["New Line Cinema","Atomic Monster"],country:"US"},1153576:{id:1153576,title:"Street Fighter",original:"Street Fighter",overview:"Em 1993, os lutadores Ryu e Ken Masters s\xE3o colocados de volta no combate quando a misteriosa Chun-Li os recruta para o pr\xF3ximo Torneio Street Fighter: uma brutal briga de socos, destino e f\xFAria. Entretanto, por tr\xE1s desse campeonato, se esconde uma conspira\xE7\xE3o mortal que os for\xE7a a encarar um ao outro e os dem\xF4nios do passado. E se eles n\xE3o fizerem, \xE9 game over!",poster:"/6gWmrC2GyDbUM1ET5EBg9lxBi7S.jpg",backdrops:["/qRN8eqYwG6HPSy0i3fKzuLrUOhp.jpg","/zDE9hd1SG9695YncbZGjSf7Z9Jk.jpg","/5H5YphHsQmkQhrw13Wv1whCZKtN.jpg","/6kJENBnZsVZuhYTSR3zZi6FUe30.jpg","/w2Gu916zS11X94CZaSLpzvfgHcG.jpg"],runtime:119,genres:["A\xE7\xE3o","Fantasia","Com\xE9dia"],cert:"14",release:"2026-10-15",world:"2026-10-13",directors:["Kitao Sakurai"],writers:["T.J. Fixman","Kitao Sakurai"],cast:[{name:"Andrew Koji",role:"Ryu"},{name:"Noah Centineo",role:"Ken Masters"},{name:"Callina Liang",role:"Chun-Li"},{name:"David Dastmalchian",role:"M. Bison"},{name:"Andrew Schulz",role:"Dan Hibiki"},{name:"Joe Anoa'i",role:"Akuma"}],studios:["Capcom","Legendary Pictures"],country:"US"},1177369:{id:1177369,title:"A Lenda de Zelda",original:"The Legend of Zelda",overview:"",poster:"/4XuaHHQ5eR9czPZPHcaaUjekx5w.jpg",backdrops:["/7iHZruybsGB7g9vrm9eeypzmpV1.jpg","/oFUHehTS11hTmKWnSkCods0piwZ.jpg","/biI4khY90m09opWzEmkdEwAo5FS.jpg","/kI3JAUYyRhbVdST6mX1di0CZIhr.jpg"],runtime:null,genres:["A\xE7\xE3o","Aventura","Fantasia"],cert:"AD",release:"2027-05-06",world:"2027-04-28",directors:["Wes Ball"],writers:["T.S. Nowlin","Derek Connolly"],cast:[{name:"Benjamin Evan Ainsworth",role:"Link"},{name:"Bo Bragason",role:"Princess Zelda"},{name:"Uli Latukefu",role:"Ganondorf"},{name:"Dichen Lachman",role:"Impa"},{name:"Sam Neill",role:""},{name:"Yvonne Strahovski",role:""}],studios:["Nintendo","Arad Productions"],country:"JP"},1226863:{id:1226863,title:"Super Mario Galaxy: O Filme",original:"The Super Mario Galaxy Movie",overview:"Depois de salvar o Reino dos Cogumelos, Mario e seus amigos se encontram em uma miss\xE3o intergal\xE1ctica para deter um novo vil\xE3o amea\xE7ador.",poster:"/b3WeTp42eJSRuE4UZfyPCOJW4c.jpg",backdrops:["/kxQiIJ4gVcD3K6o14MJ72p5yRcE.jpg","/9Z2uDYXqJrlmePznQQJhL6d92Rq.jpg","/uA64sXP52d4uHGMVdQf5aeBLzwU.jpg","/kDOl4pwu6QSqcOD3O7FyxY2p95m.jpg","/n5OWzWUgjl5r1VFbbx72cCgcj8X.jpg"],runtime:95,genres:["Fam\xEDlia","Com\xE9dia","Aventura"],cert:"L",release:"2026-04-01",world:"2026-04-01",directors:["Aaron Horvath","Michael Jelenic"],writers:["Matthew Fogel"],cast:[{name:"Chris Pratt",role:"Mario (voz)"},{name:"Charlie Day",role:"Luigi (voz)"},{name:"Anya Taylor-Joy",role:"Princess Peach (voz)"},{name:"Jack Black",role:"Bowser (voz)"},{name:"Keegan-Michael Key",role:"Toad (voz)"},{name:"Benny Safdie",role:"Bowser Junior (voz)"}],studios:["Illumination","Universal Pictures"],country:"US"},1423191:{id:1423191,title:"Resident Evil",original:"Resident Evil",overview:"Bryan, um tranquilo entregador de \xF3rg\xE3os, \xE9 enviado para uma entrega noturna no Hospital Geral de Raccoon City. No caminho por uma estrada montanhosa coberta de neve, ele acidentalmente atropela uma mulher desconhecida. Ela sobrevive, mas algo est\xE1 muito errado. Ao tentar ajudar, Bryan se depara com um surto em larga escala envolvendo muta\xE7\xF5es horr\xEDveis com tent\xE1culos e monstruosidades bioengenheiradas.",poster:"/bvBTdNaWVPrHKjyPFnsigZJsKdD.jpg",backdrops:["/3icyRAqgakNcQn6aDVz9libFmBA.jpg","/vqNSvCFknXObgqn7nOFrJVEeGht.jpg","/8R79AZjX1Bt4219Ub3CrRMsPQsW.jpg","/1CIaRYKf3zg2Xyce1CSfCMg2Vfw.jpg","/wlPVfeP99fpTLkTRqlJakRN8d2F.jpg"],runtime:90,genres:["Terror","Fic\xE7\xE3o cient\xEDfica","Aventura"],cert:"18",release:"2026-09-17",world:"2026-09-16",directors:["Zach Cregger"],writers:["Shay Hatten","Zach Cregger"],cast:[{name:"Austin Abrams",role:"Bryan"},{name:"Paul Walter Hauser",role:"Paul"},{name:"Kali Reis",role:"Maxine"},{name:"Zach Cherry",role:"Carl"},{name:"Johnno Wilson",role:"Officer Wilson"},{name:"Shaun W. Loeser",role:"Puker"}],studios:["Constantin Film","Subconscious"],country:"US"}},tv:{}};export{o as media,e as post};
